cypress_script:
describe('Links Page API Response Handling', () => {
  it('should navigate to the Home page on clicking the Home link', () => {
    cy.visit('https://demoqa.com/links');
    cy.get('#simpleLink').click();
    cy.url().should('eq', 'https://demoqa.com/');
  });

  it('should not navigate anywhere when clicking the Created link', () => {
    cy.visit('https://demoqa.com/links');
    cy.get('#created').click();
    cy.url().should('eq', 'https://demoqa.com/links');
    cy.get('#simpleLink').should('be.visible');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Links Page API Response Handling', () => {
  test('should navigate to the Home page on clicking the Home link', async ({ page }) => {
    await page.goto('https://demoqa.com/links');
    await page.click('#simpleLink');
    await expect(page).toHaveURL('https://demoqa.com/');
  });

  test('should not navigate anywhere when clicking the Created link', async ({ page }) => {
    await page.goto('https://demoqa.com/links');
    await page.click('#created');
    await expect(page).toHaveURL('https://demoqa.com/links');
    await expect(page.locator('#simpleLink')).toBeVisible();
  });
});
